// <auto-generated />
namespace LiveScore.Soccers.Features.Matches.DataProviders
{
    using LiveScore.Features.Matches.Models;
    using LiveScore.Shared.Configurations;
    using LiveScore.Shared.Models.Dtos;
    using Newtonsoft.Json;
    using System;
    using System.IO;
    using System.Linq;
    using System.Threading.Tasks;

    public class StaticMatchApi : IMatchApi
    {
        private static Random random = new Random();
        private readonly IAppSettings appSettings;

        public StaticMatchApi(IAppSettings appSettings)
        {
            this.appSettings = appSettings;
        }

        public Task<DailyScheduleDto> GetDailySchedules(
            int sportId,
            DateTime from,
            DateTime to,
            string language)
        {
            // Temporary for hardcode, please ignore it
            var jsonData = File.ReadAllText($"{appSettings.AppPath}/App_Data/staticdata/daily-schedule.json");
            var dailyScheduleDto = JsonConvert.DeserializeObject<DailyScheduleDto>(jsonData);

            if (appSettings.AutoGenerateStatus)
            {
                AutoGenerateStatus(dailyScheduleDto, from);
            }

            dailyScheduleDto.results = dailyScheduleDto.results.Where(result
                => result.sport_event.scheduled >= from && result.sport_event.scheduled <= to);

            return Task.FromResult(dailyScheduleDto);
        }

        private void AutoGenerateStatus(DailyScheduleDto dailyScheduleDto, DateTime date)
        {
            foreach (var result in dailyScheduleDto.results)
            {
                AutoGenerateCompetitorName(result);

                AutoGenerateScheduledDate(result, date);
                AutoGenerateStatus(result);
            }
        }

        private static void AutoGenerateCompetitorName(Result result)
        {
            foreach (var competitor in result.sport_event.competitors)
            {
                competitor.name = $"{competitor.name} - {CreateString(5)}";
            }
        }

        private void AutoGenerateStatus(Result result)
        {
            if (result.sport_event.scheduled > DateTime.Now.ToUniversalTime())
            {
                var randomStatus = CreateEventStatusPre();

                result.sport_event_status.status = randomStatus;
                result.sport_event_status.match_status = randomStatus;

                result.sport_event_status.home_score = 0;
                result.sport_event_status.away_score = 0;
            }
            else if (result.sport_event.scheduled < DateTime.Now.ToUniversalTime().Date)
            {
                result.sport_event_status.status = CreateEventStatusPost();

                if (result.sport_event_status.status.Equals(MatchStatus.Abandoned.Value))
                {
                    result.sport_event_status.match_status = MatchStatus.Abandoned.Value;
                }
                else
                {
                    result.sport_event_status.match_status = CreateMatchStatusPost();
                }
            }
            else
            {
                result.sport_event_status.status = MatchStatus.Live.Value;
                result.sport_event_status.match_status = CreateLiveMatchStatus();
            }
        }

        private void AutoGenerateScheduledDate(Result result, DateTime date)
        {
            var dates = new[]
            {
                date.AddDays(-1),
                date,
                date.AddDays(1),
                date.AddDays(2),
            };

            var randomDate = dates[random.Next(0, dates.Length)];

            var dateFormat = string.Format("{0}-{1}-{2}T{3}:{4}:{5}+00:00",
               randomDate.Year.ToString("0000"),
               randomDate.Month.ToString("00"),
               randomDate.Day.ToString("00"),
               result.sport_event.scheduled.ToUniversalTime().Hour.ToString("00"),
               result.sport_event.scheduled.ToUniversalTime().Minute.ToString("00"),
               result.sport_event.scheduled.ToUniversalTime().Second.ToString("00"));

            result.sport_event.scheduled = DateTime.Parse(dateFormat);
        }

        internal static string CreateString(int stringLength)
        {

            const string allowedChars = "ABCDEFGHJKLMNOPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz0123456789!@$?_-";
            char[] chars = new char[stringLength];

            for (int i = 0; i < stringLength; i++)
            {
                chars[i] = allowedChars[random.Next(0, allowedChars.Length)];
            }

            return new string(chars);
        }

        private string CreateEventStatusPre()
        {
            var eventStatuses = new[]
               {
                    MatchStatus.NotStarted.Value,
                    MatchStatus.Postponed.Value,
                    MatchStatus.StartDelayed.Value,
                    MatchStatus.Cancelled.Value
                };

            return eventStatuses[random.Next(0, eventStatuses.Length)];
        }

        private string CreateMatchStatusPost()
        {
            var eventStatuses = new[]
               {                    
                    MatchStatus.Ended.Value,
                    MatchStatus.EndedAfterPenalties.Value,
                    MatchStatus.EndedExtraTime.Value,
                    MatchStatus.FullTime.Value
                };

            return eventStatuses[random.Next(0, eventStatuses.Length)];
        }

        private string CreateEventStatusPost()
        {
            var eventStatuses = new[]
               {
                    MatchStatus.Abandoned.Value,                   
                    MatchStatus.Closed.Value
                };

            return eventStatuses[random.Next(0, eventStatuses.Length)];
        }

        private string CreateLiveMatchStatus()
        {
            var eventStatuses = new[]
               {
                    MatchStatus.FirstHaft.Value,
                    MatchStatus.SecondHaft.Value,
                    MatchStatus.Overtime.Value,
                    MatchStatus.Penalties.Value,
                    MatchStatus.AwaitingPenalties.Value,
                    MatchStatus.Pause.Value,
                    MatchStatus.Interrupted.Value,
                    MatchStatus.Delayed.Value,
                    MatchStatus.FirstHaftExtra.Value,
                    MatchStatus.SecondHaftExtra.Value,
                    MatchStatus.AwaitingExtraTime.Value,
                    MatchStatus.ExtraTime.Value
                };

            return eventStatuses[random.Next(0, eventStatuses.Length)];
        }
    }
}